<?php
use App\Application\Liquidaciones\{ConsultarLiquidaciones,GestionarLiquidaciones,GestionarPeriodos,CalcularLiquidaciones};
use App\Application\Operacion\ReglasOperativas;
use Illuminate\Support\Facades\Gate;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Livewire\Component;
use Livewire\WithPagination;
use Livewire\Attributes\Locked;
use Mary\Traits\Toast;
new class extends Component {
 use WithPagination,Toast;
 public string $search=''; public string $state=''; public string $periodFilter=''; public string $reason='';
 public array $periodForm=['uuid'=>'','desde'=>'','motivo'=>''];
 public array $adjustForm=['uuid'=>'','tipo'=>'ajuste','importe'=>'','origen_uuid'=>'','motivo'=>''];
 public array $payForm=['uuid_externo'=>'','metodo'=>'','pagado_at'=>''];
 public array $ruleForm=['precio_litro'=>'','conflicto_tarifas'=>'bloquear','perdida_incluye_bonos'=>null,'motivo'=>''];
 #[Locked] public ?string $selected=null;
 public function boot(): void { Gate::authorize('operar-liquidaciones'); }
 public function mount(): void { $this->periodForm['uuid']=(string)Str::uuid(); }
 public function updatedSearch(): void { Gate::authorize('operar-liquidaciones'); $this->resetPage(); }
 public function updatedState(): void { Gate::authorize('operar-liquidaciones'); $this->resetPage(); }
 public function show(string $uuid): void { Gate::authorize('operar-liquidaciones'); app(ConsultarLiquidaciones::class)->find(auth()->id(),$uuid); $this->selected=$uuid; $this->adjustForm['uuid']=(string)Str::uuid(); $this->payForm=['uuid_externo'=>(string)Str::uuid(),'metodo'=>'','pagado_at'=>now()->format('Y-m-d\TH:i:s')]; $this->resetValidation(); }
 public function createPeriod(): void { Gate::authorize('administrar-liquidaciones'); $this->perform(function(): void { app(GestionarPeriodos::class)->create(auth()->id(),$this->periodForm); $this->periodForm['uuid']=(string)Str::uuid(); }); }
 public function periodAction(string $uuid,string $action): void { Gate::authorize($action==='calcular'?'operar-liquidaciones':'administrar-liquidaciones'); $this->perform(function() use($uuid,$action): void { match($action) { 'cerrar'=>app(GestionarPeriodos::class)->close(auth()->id(),$uuid,$this->reason),'calcular'=>app(CalcularLiquidaciones::class)->calculate(auth()->id(),$uuid,$this->reason),'aprobar'=>app(GestionarLiquidaciones::class)->approve(auth()->id(),$uuid,$this->reason),'anular'=>app(GestionarPeriodos::class)->annul(auth()->id(),$uuid,$this->reason),default=>abort(404) }; }); }
 public function adjust(): void { Gate::authorize('operar-liquidaciones'); $this->perform(function(): void { app(GestionarLiquidaciones::class)->adjustment(auth()->id(),$this->selected??'',$this->adjustForm); $this->adjustForm['uuid']=(string)Str::uuid(); }); }
 public function decide(string $uuid,string $decision): void { Gate::authorize('administrar-liquidaciones'); $this->perform(fn()=>app(GestionarLiquidaciones::class)->decideAdjustment(auth()->id(),$uuid,['decision'=>$decision,'motivo'=>$this->reason])); }
 public function pay(): void { Gate::authorize('operar-liquidaciones'); $this->perform(fn()=>app(GestionarLiquidaciones::class)->pay(auth()->id(),$this->selected??'',$this->payForm)); }
 public function saveRules(): void { Gate::authorize('administrar-liquidaciones'); $this->perform(fn()=>app(GestionarPeriodos::class)->configure(auth()->id(),$this->ruleForm)); }
 private function perform(Closure $operation): void { $this->resetValidation(); try { $operation(); $this->success('Operación registrada.'); } catch(ValidationException $e) { foreach($e->errors() as $key=>$messages) { $this->addError($key,$messages[0]); } } catch(\Illuminate\Auth\Access\AuthorizationException $e) { throw $e; } catch(Throwable $e) { report($e); $this->addError('operacion','No se pudo completar la operación. Puedes reintentar.'); } }
 public function with(): array { $q=app(ConsultarLiquidaciones::class); $detail=$this->selected?$q->find(auth()->id(),$this->selected):null; return ['records'=>$q->listing(auth()->id(),['buscar'=>$this->search,'estado'=>$this->state,'periodo'=>$this->periodFilter]),'periods'=>$q->periods(auth()->id()),'detail'=>$detail,'totals'=>$detail?app(GestionarLiquidaciones::class)->totals($detail):[],'rule'=>app(ReglasOperativas::class)->current('liquidaciones')]; }
}; ?>
