 @can('administrar-liquidaciones')<x-card title="Crear periodo" shadow><x-form wire:submit="createPeriod"><x-input label="Jueves inicial" type="date" wire:model="periodForm.desde" /><x-textarea label="Motivo" wire:model="periodForm.motivo" /><x-slot:actions><x-button label="Crear periodo" type="submit" spinner="createPeriod" class="btn-primary" /></x-slot:actions></x-form></x-card>@endcan
