 <div class="flex gap-3 my-3"><x-button label="Comprobante imprimible" :link="route('admin.liquidaciones.comprobante', $detail->uuid)" external /><x-button label="Descargar PDF" :link="route('admin.liquidaciones.pdf', $detail->uuid)" external /></div><h3 class="font-semibold mt-4">Ajustes y decisiones</h3>@forelse($detail->ajustes as $adjustment)<div class="border rounded p-3 my-2"><p>{{ $adjustment->tipo }} · S/ {{ $adjustment->importe }} · {{ $adjustment->estado }} · {{ $adjustment->motivo }} · {{ $adjustment->comentario }}</p>@can('administrar-liquidaciones')@if($adjustment->estado==='pendiente')<x-button label="Aprobar ajuste" wire:click="decide('{{ $adjustment->uuid }}','aprobado')" spinner="decide" /><x-button label="Rechazar ajuste" wire:click="decide('{{ $adjustment->uuid }}','rechazado')" spinner="decide" />@endif @endcan</div>@empty<p>Sin ajustes.</p>@endforelse
 @if(in_array($detail->estado,['calculada','aprobada']))<x-form wire:submit="adjust"><x-select label="Tipo" wire:model="adjustForm.tipo" :options="[['id'=>'ajuste','name'=>'Ajuste'],['id'=>'bono','name'=>'Bono']]" /><x-input label="Importe S/ (negativo para descuento)" wire:model="adjustForm.importe" /><x-input label="UUID de liquidación pagada anterior (opcional)" wire:model="adjustForm.origen_uuid" /><x-textarea label="Motivo del ajuste" wire:model="adjustForm.motivo" /><x-slot:actions><x-button label="Solicitar ajuste" type="submit" spinner="adjust" /></x-slot:actions></x-form>@endif
